-- Litemacro Marketplace Supabase setup / upgrade.
-- Run this in the Supabase SQL Editor for the Litemacro project.
--
-- This version does not use Discord OAuth. Uploads are anonymous and are
-- rate-limited by a local uploader id generated by the mod.

create extension if not exists pgcrypto;

create table if not exists public.marketplace_presets (
    id uuid primary key default gen_random_uuid(),
    created_at timestamptz not null default now(),
    slug text not null unique,
    name text not null,
    author_name text not null,
    description text not null default '',
    tags text[] not null default '{}',
    game_version text,
    litemacro_version text,
    likes_count integer not null default 0,
    downloads_count integer not null default 0,
    file_path text not null,
    published boolean not null default true,
    updated_at timestamptz not null default now(),
    author_user_id uuid,
    storage_bucket text not null default 'graphs',
    author_avatar_url text,
    uploader_install_id text,
    macro_json jsonb
);

alter table public.marketplace_presets add column if not exists slug text;
alter table public.marketplace_presets add column if not exists name text;
alter table public.marketplace_presets add column if not exists author_name text;
alter table public.marketplace_presets add column if not exists description text not null default '';
alter table public.marketplace_presets add column if not exists tags text[] not null default '{}';
alter table public.marketplace_presets add column if not exists game_version text;
alter table public.marketplace_presets add column if not exists litemacro_version text;
alter table public.marketplace_presets add column if not exists likes_count integer not null default 0;
alter table public.marketplace_presets add column if not exists downloads_count integer not null default 0;
alter table public.marketplace_presets add column if not exists file_path text;
alter table public.marketplace_presets add column if not exists published boolean not null default true;
alter table public.marketplace_presets add column if not exists updated_at timestamptz not null default now();
alter table public.marketplace_presets add column if not exists author_user_id uuid;
alter table public.marketplace_presets add column if not exists storage_bucket text not null default 'graphs';
alter table public.marketplace_presets add column if not exists author_avatar_url text;
alter table public.marketplace_presets add column if not exists uploader_install_id text;
alter table public.marketplace_presets add column if not exists macro_json jsonb;

alter table public.marketplace_presets alter column file_path set not null;
alter table public.marketplace_presets alter column published set default true;
alter table public.marketplace_presets alter column storage_bucket set default 'graphs';

create unique index if not exists marketplace_presets_slug_key on public.marketplace_presets (slug);
create index if not exists marketplace_presets_published_updated_idx on public.marketplace_presets (published, updated_at desc);
create index if not exists marketplace_presets_uploader_idx on public.marketplace_presets (uploader_install_id, created_at desc);

create table if not exists public.litemacro_marketplace_likes (
    preset_id uuid not null references public.marketplace_presets(id) on delete cascade,
    liker_install_id text not null,
    created_at timestamptz not null default now(),
    primary key (preset_id, liker_install_id)
);

create index if not exists litemacro_marketplace_likes_liker_idx on public.litemacro_marketplace_likes (liker_install_id, created_at desc);

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
    new.updated_at = now();
    return new;
end;
$$;

drop trigger if exists marketplace_presets_set_updated_at on public.marketplace_presets;
create trigger marketplace_presets_set_updated_at
before update on public.marketplace_presets
for each row execute function public.set_updated_at();

-- Remove old authenticated publish/sign-in helper functions from earlier marketplace builds.
drop function if exists public.publish_marketplace_preset(text, text, text, text, text[], text, text, text);
drop function if exists public.publish_marketplace_preset(text, text, text, text, text[], text, text, text, boolean);
drop function if exists public.publish_marketplace_preset(text, text, text, text, text[], text, text, text, text, boolean);
drop function if exists public.update_marketplace_preset_metadata(uuid, text, text, text[], text, text);
drop function if exists public.update_marketplace_preset_metadata(uuid, text, text, text[], text, text, boolean);
drop function if exists public.update_marketplace_preset_metadata(uuid, text, text, text[], text, text, boolean, text, text);
drop function if exists public.fetch_my_marketplace_presets();
drop function if exists public.fetch_my_marketplace_preset_likes();
drop function if exists public.toggle_marketplace_preset_like(uuid);
drop function if exists public.record_marketplace_download(uuid);
