drop function if exists public.like_litemacro_marketplace_preset(uuid, text);

create or replace function public.normalize_litemacro_tags(preset_tags text[])
returns text[]
language sql
immutable
as $$
    with normalized as (
        select distinct left(trim(lower(tag)), 32) as tag
        from unnest(coalesce(preset_tags, array[]::text[])) as tag
        where coalesce(trim(tag), '') <> ''
        limit 12
    ),
    collected as (
        select coalesce(array_agg(tag), array[]::text[]) as tags
        from normalized
    )
    select case
        when 'litemacro' = any(tags) then tags
        else array_prepend('litemacro', tags)
    end
    from collected;
$$;

create or replace function public.unique_litemacro_slug(base_slug text)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    normalized text;
    candidate text;
    suffix integer := 2;
begin
    normalized := regexp_replace(lower(coalesce(trim(base_slug), '')), '[^a-z0-9]+', '-', 'g');
    normalized := regexp_replace(normalized, '(^-+|-+$)', '', 'g');

    if normalized = '' then
        normalized := 'litemacro-macro';
    end if;

    normalized := left(normalized, 80);
    candidate := normalized;

    while exists (select 1 from public.marketplace_presets where slug = candidate) loop
        candidate := left(normalized, 76) || '-' || suffix::text;
        suffix := suffix + 1;
    end loop;

    return candidate;
end;
$$;

create or replace function public.submit_litemacro_marketplace_preset(
    uploader_install_id text,
    preset_slug text,
    preset_name text,
    preset_author_name text,
    preset_description text,
    preset_tags text[],
    preset_game_version text,
    preset_litemacro_version text,
    macro_json jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    normalized_uploader text;
    upload_count integer;
    remaining integer;
    preset_id uuid := gen_random_uuid();
    final_slug text;
    normalized_tags text[];
begin
    normalized_uploader := nullif(trim(coalesce(uploader_install_id, '')), '');
    if normalized_uploader is null then
        raise exception 'Uploader id is required.' using errcode = 'P0001';
    end if;

    if macro_json is null or jsonb_typeof(macro_json) <> 'object' then
        raise exception 'Macro JSON is required.' using errcode = 'P0001';
    end if;

    select count(*)
    into upload_count
    from public.marketplace_presets presets
    where presets.uploader_install_id = normalized_uploader;

    if upload_count >= 5 then
        return jsonb_build_object(
            'accepted', false,
            'upload_count', upload_count,
            'remaining', 0,
            'message', 'Upload limit reached. Each user can upload up to 5 macros.'
        );
    end if;

    final_slug := public.unique_litemacro_slug(preset_slug);
    normalized_tags := public.normalize_litemacro_tags(preset_tags);

    insert into public.marketplace_presets (
        id,
        slug,
        name,
        author_name,
        description,
        tags,
        game_version,
        litemacro_version,
        likes_count,
        downloads_count,
        storage_bucket,
        file_path,
        published,
        uploader_install_id,
        macro_json
    )
    values (
        preset_id,
        final_slug,
        left(coalesce(nullif(trim(preset_name), ''), final_slug), 96),
        left(coalesce(nullif(trim(preset_author_name), ''), 'Litemacro user'), 64),
        left(coalesce(preset_description, ''), 1200),
        normalized_tags,
        nullif(trim(coalesce(preset_game_version, '')), ''),
        nullif(trim(coalesce(preset_litemacro_version, '')), ''),
        0,
        0,
        'database',
        'database/' || preset_id::text || '.json',
        true,
        normalized_uploader,
        macro_json
    );

    upload_count := upload_count + 1;
    remaining := greatest(0, 5 - upload_count);

    return jsonb_build_object(
        'accepted', true,
        'upload_count', upload_count,
        'remaining', remaining,
        'message', 'Uploaded to Litemacro Marketplace.'
    );
end;
$$;

create or replace function public.download_litemacro_marketplace_preset(target_preset_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    preset_json jsonb;
begin
    select macro_json
    into preset_json
    from public.marketplace_presets
    where id = target_preset_id
      and published = true
      and storage_bucket = 'database'
      and macro_json is not null;

    if preset_json is null then
        raise exception 'Marketplace macro JSON was not found.' using errcode = 'P0001';
    end if;

    return preset_json;
end;
$$;

create or replace function public.increment_preset_downloads(target_preset_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
    update public.marketplace_presets
    set downloads_count = downloads_count + 1,
        updated_at = now()
    where id = target_preset_id
      and published = true;
end;
$$;

create or replace function public.like_litemacro_marketplace_preset(
    target_preset_id uuid,
    liker_install_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    normalized_liker text;
    liked_preset public.marketplace_presets;
begin
    normalized_liker := nullif(trim(coalesce(liker_install_id, '')), '');
    if normalized_liker is null then
        raise exception 'Liker id is required.' using errcode = 'P0001';
    end if;

    insert into public.litemacro_marketplace_likes (preset_id, liker_install_id)
    select target_preset_id, normalized_liker
    where exists (
        select 1
        from public.marketplace_presets
        where id = target_preset_id
          and published = true
    )
    on conflict do nothing;

    update public.marketplace_presets presets
    set likes_count = (
            select count(*)
            from public.litemacro_marketplace_likes likes
            where likes.preset_id = presets.id
        ),
        updated_at = now()
    where presets.id = target_preset_id
      and presets.published = true
    returning * into liked_preset;

    if liked_preset.id is null then
        raise exception 'Marketplace macro was not found.' using errcode = 'P0001';
    end if;

    return to_jsonb(liked_preset);
end;
$$;

alter table public.marketplace_presets enable row level security;
alter table public.litemacro_marketplace_likes enable row level security;

drop policy if exists "Public can read published marketplace presets" on public.marketplace_presets;
drop policy if exists "Public can read published presets" on public.marketplace_presets;
drop policy if exists "Owners can read their marketplace presets" on public.marketplace_presets;
drop policy if exists "authenticated users can read own presets" on public.marketplace_presets;
drop policy if exists "authenticated users can insert own presets" on public.marketplace_presets;
drop policy if exists "authenticated users can update own presets" on public.marketplace_presets;
drop policy if exists "authenticated users can delete own presets" on public.marketplace_presets;
drop policy if exists "Marketplace moderators can read all presets" on public.marketplace_presets;

create policy "Public can read published marketplace presets"
on public.marketplace_presets
for select
to anon, authenticated
using (published = true);

grant usage on schema public to anon, authenticated;
grant select on public.marketplace_presets to anon, authenticated;
revoke insert, update, delete on public.marketplace_presets from anon, authenticated;
revoke all on public.litemacro_marketplace_likes from anon, authenticated;
grant execute on function public.submit_litemacro_marketplace_preset(text, text, text, text, text, text[], text, text, jsonb) to anon, authenticated;
grant execute on function public.download_litemacro_marketplace_preset(uuid) to anon, authenticated;
grant execute on function public.increment_preset_downloads(uuid) to anon, authenticated;
grant execute on function public.like_litemacro_marketplace_preset(uuid, text) to anon, authenticated;

-- Optional public storage compatibility for older marketplace rows that still
-- point at files in the public "graphs" bucket.
insert into storage.buckets (id, name, public)
values ('graphs', 'graphs', true)
on conflict (id) do update set public = true;

drop policy if exists "graph files are publicly readable" on storage.objects;
create policy "graph files are publicly readable"
on storage.objects
for select
to anon, authenticated
using (bucket_id = 'graphs');

-- Supabase/PostgREST can keep an old function schema cached for a short time.
-- Reload it immediately so /rest/v1/rpc/submit_litemacro_marketplace_preset
-- becomes available after this script finishes.
notify pgrst, 'reload schema';

select
    'Litemacro marketplace RPC setup complete' as status,
    exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = 'submit_litemacro_marketplace_preset'
    ) as submit_rpc_installed,
    exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = 'download_litemacro_marketplace_preset'
    ) as download_rpc_installed,
    exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = 'increment_preset_downloads'
    ) as download_count_rpc_installed,
    exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = 'like_litemacro_marketplace_preset'
    ) as like_rpc_installed;
